import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZRound38FragmentChoiceOracle extends GhidraScript{
 static final long RET=0x12345000L,S=0x7fff0000L;long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(i*8);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<1024;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{byte[]plane=new byte[16384];java.util.Arrays.fill(plane,(byte)66);int[]ds={0,-1,1,-128,128,127,129},codes={0,7,9,1,23,18,5,66};for(int i=0;i<7;i++)plane[4256+ds[i]]=(byte)codes[((s>>(i%3*3))^(s/(i+1)))&7];e.writeMemory(toAddr(0x58aaaa),plane);put(e,0x622d50,2,2048);put(e,0x622d52,2,2048);put(e,0x4a6f4f,1,0);put(e,0x4a6f43,1,s/512);put(e,0x4d18ee,1,1);put(e,0x4a6f42,1,1);for(long pc:new long[]{RET,0x41eb90,0x40e920,0x41fe30,0x41cab0,0x41fda0,0x420e20,0x409c50,0x42fdb0})e.setBreakpoint(toAddr(pc));e.writeRegister("ESP",S);put(e,S,4,RET);put(e,S+4,4,500);put(e,S+8,4,0);e.writeRegister("ECX",0);e.writeRegister("EDX",500);if(!e.run(toAddr(0x420200),null,monitor))throw new Exception(e.getLastError());int kind=0,cell=-999;while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==0x41fda0||pc==0x420e20){kind=pc==0x41fda0?1:2;cell=(short)e.readRegister("EDX").longValue();}else if(pc==0x409c50||pc==0x42fdb0){kind=3;cell=(short)read(e,0x4a9424,2);}e.writeRegister("EAX",0);long ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}out.println(s+","+kind+","+cell+","+(short)read(e,0x4a9424,2));}finally{e.dispose();}}}}
}